//! `IfPatternMatchProcessor.getLastExprentWhen` and `isStatementMatchThrow` against vectors
//! from the real Vineflower 1.12.0 classes (`data/b16/GenB16Oracle.java` ->
//! `data/b16/b16_golden.txt`, regenerated by `data/b16/gen.sh`). Each scenario mirrors the
//! Java driver statement by statement, so ids from `EXPRESSION_COUNTER` line up with Java's.

use kuna_jvm::basic_block_statement::BasicBlockStatement;
use kuna_jvm::byte_cursor::ByteCursor;
use kuna_jvm::code_type::CodeType;
use kuna_jvm::const_exprent::{ConstExprent, ConstValue};
use kuna_jvm::counter_container::CounterContainer;
use kuna_jvm::decompiler_context::DecompilerContext;
use kuna_jvm::exit_exprent::{ExitExprent, Type as ExitType};
use kuna_jvm::exprent::Exprent;
use kuna_jvm::function_exprent::{FunctionExprent, FunctionType};
use kuna_jvm::if_pattern_match_processor::IfPatternMatchProcessor;
use kuna_jvm::new_exprent::NewExprent;
use kuna_jvm::record_helper::RecordHelper;
use kuna_jvm::struct_class::StructClass;
use kuna_jvm::var_exprent::VarExprent;
use kuna_jvm::var_type::VarType;

use crate::common;

const GOLDEN: &str = include_str!("data/b16/b16_golden.txt");
const B16REC: &[u8] = include_bytes!("data/b16/B16Rec.class");

fn reset() {
    let counters = DecompilerContext::get_counter_container();
    counters.set_counter(CounterContainer::EXPRESSION_COUNTER, 1);
    counters.set_counter(CounterContainer::STATEMENT_COUNTER, 1);
}

fn obj(cls: &str) -> VarType {
    VarType::new_value(CodeType::Object, 0, cls)
}

fn var(index: i32) -> Exprent {
    VarExprent::new(index, Some(obj("java/lang/Object")), None).0
}

fn func(t: FunctionType, ops: Vec<Exprent>) -> Exprent {
    FunctionExprent::new(t, ops, None).0
}

fn iof(index: i32, cls: &str) -> Exprent {
    let v = var(index);
    let c = ConstExprent::new(obj(cls), None, None).0;
    func(FunctionType::Instanceof, vec![v, c])
}

fn cb(v: i32) -> Exprent {
    ConstExprent::new_int(v, true, None).0
}

fn ci(v: i32) -> Exprent {
    ConstExprent::new_int(v, false, None).0
}

fn last(out: &mut Vec<String>, name: &str, cond: Exprent) {
    for t in [1, 0] {
        for o in [1, 0] {
            let e = IfPatternMatchProcessor::get_last_exprent_when(cond, t == 1, o == 1);
            let id = e.map_or("null".to_string(), |e| e.get_id().to_string());
            out.push(format!("last {name} {t} {o} {id}"));
        }
    }
}

fn exit(t: ExitType, value: Exprent) -> Exprent {
    ExitExprent::new(t, Some(value), None, None, None).0
}

fn new_obj(cls: &str) -> Exprent {
    NewExprent::new(obj(cls), Vec::<Exprent>::new(), None).0
}

fn thr(out: &mut Vec<String>, name: &str, exprents: Vec<Exprent>) {
    let bb = BasicBlockStatement::create();
    bb.get_exprents().unwrap().add_all(exprents);
    let matched = IfPatternMatchProcessor::is_statement_match_throw(bb.0);
    out.push(format!("throw {name} {}", i32::from(matched)));
}

#[test]
fn last_exprent_and_match_throw_match_vineflower() {
    let _g = common::install_default_context();
    let mut out = Vec::new();

    reset();
    last(&mut out, "iof", iof(1, "java/lang/String"));
    reset();
    last(&mut out, "var", var(1));
    reset();
    let c = func(FunctionType::BooleanAnd, vec![iof(1, "A"), iof(2, "B")]);
    last(&mut out, "and", c);
    reset();
    let c = func(FunctionType::BooleanOr, vec![iof(1, "A"), iof(2, "B")]);
    last(&mut out, "or", c);
    reset();
    let c = func(FunctionType::BoolNot, vec![iof(1, "A")]);
    last(&mut out, "not", c);
    reset();
    let c = func(FunctionType::Eq, vec![iof(1, "A"), cb(0)]);
    last(&mut out, "eq_false", c);
    reset();
    let c = func(FunctionType::Eq, vec![iof(1, "A"), cb(1)]);
    last(&mut out, "eq_true", c);
    reset();
    let c = func(FunctionType::Ne, vec![iof(1, "A"), cb(0)]);
    last(&mut out, "ne_false", c);
    reset();
    let c = func(FunctionType::Ne, vec![iof(1, "A"), cb(1)]);
    last(&mut out, "ne_true", c);
    reset();
    let c = func(FunctionType::Eq, vec![var(1), ci(0)]);
    last(&mut out, "eq_int", c);
    reset();
    let lhs = iof(1, "A");
    let rhs = ConstExprent::new(
        VarType::new(CodeType::Boolean),
        Some(ConstValue::Int(0)),
        None,
    )
    .0;
    let c = func(FunctionType::Eq, vec![lhs, rhs]);
    last(&mut out, "eq_boolcopy", c);
    reset();
    let c = func(FunctionType::Ne, vec![iof(1, "A"), var(2)]);
    last(&mut out, "ne_var", c);
    reset();
    let c = func(FunctionType::Lt, vec![var(1), var(2)]);
    last(&mut out, "lt", c);
    reset();
    let inner = func(FunctionType::BooleanAnd, vec![iof(1, "A"), iof(2, "B")]);
    let c = func(FunctionType::BoolNot, vec![inner]);
    last(&mut out, "not_and", c);
    reset();
    let or = func(FunctionType::BooleanOr, vec![iof(1, "A"), iof(2, "B")]);
    let not = func(FunctionType::BoolNot, vec![or]);
    let ne = func(FunctionType::Ne, vec![iof(3, "C"), cb(0)]);
    let c = func(FunctionType::BooleanAnd, vec![not, ne]);
    last(&mut out, "nested", c);
    reset();
    let a = iof(1, "A");
    let b = iof(2, "B");
    let eq = func(FunctionType::Eq, vec![iof(3, "C"), cb(1)]);
    let and = func(FunctionType::BooleanAnd, vec![b, eq]);
    let c = func(FunctionType::BooleanOr, vec![a, and]);
    last(&mut out, "or_and", c);

    reset();
    let e = exit(ExitType::Throw, new_obj("java/lang/MatchException"));
    thr(&mut out, "match", vec![e]);
    reset();
    let e = exit(ExitType::Throw, new_obj("java/lang/IllegalStateException"));
    thr(&mut out, "other", vec![e]);
    reset();
    let e = exit(ExitType::Throw, new_obj("java/lang/MatchException"));
    let v = var(1);
    thr(&mut out, "two", vec![e, v]);
    reset();
    let e = exit(ExitType::Return, new_obj("java/lang/MatchException"));
    thr(&mut out, "return", vec![e]);
    reset();
    let e = exit(ExitType::Throw, var(1));
    thr(&mut out, "var", vec![e]);
    reset();
    let v = var(1);
    thr(&mut out, "not_exit", vec![v]);
    reset();
    thr(&mut out, "empty", vec![]);

    let expected: Vec<&str> = GOLDEN.lines().collect();
    assert_eq!(out.len(), expected.len());
    for (got, want) in out.iter().zip(&expected) {
        assert_eq!(got, want);
    }
}

#[test]
fn record_fields_and_accessor_annotations() {
    let _g = common::install_default_context();
    let cl = StructClass::create(&mut ByteCursor::new(B16REC.to_vec()), true);
    let components = cl.get_record_components().expect("record components");
    let names: Vec<String> = components.iter().map(|c| c.get_name()).collect();
    assert_eq!(names, ["a", "b", "rest"]);

    for field in cl.get_fields().to_vec() {
        let hidden = RecordHelper::is_hidden_record_field(Some(&components), field);
        assert_eq!(hidden, field.get_name() != "s", "{}", field.get_name());
        assert!(!RecordHelper::is_hidden_record_field(None, field));
    }

    let a = cl.get_method("a", "()I").expect("a()");
    let b = cl.get_method("b", "()Ljava/lang/String;").expect("b()");
    assert!(RecordHelper::has_annotations(a));
    assert!(!RecordHelper::has_annotations(b));
}
